from .repository import existing_emails, put_contact

_CONTACT_FIELDS = frozenset(("email", "name"))

def add_contact(connection, email, name):
    with connection:
        put_contact(connection, email, name)

def _normalize_row(row):
    if not isinstance(row, dict):
        raise ValueError("contact row must be an object")
    keys = set(row)
    if keys != _CONTACT_FIELDS:
        missing = sorted(_CONTACT_FIELDS - keys)
        unknown = sorted(str(k) for k in keys - _CONTACT_FIELDS)
        raise ValueError(f"contact row must have exactly email and name (missing={missing}, unknown={unknown})")
    email = row["email"]
    name = row["name"]
    if not isinstance(email, str) or not isinstance(name, str):
        raise ValueError("email and name must be strings")
    email = email.strip().lower()
    name = name.strip()
    if email.count("@") != 1:
        raise ValueError("email must contain exactly one '@'")
    local, domain = email.split("@")
    if not local or not domain:
        raise ValueError("email must have nonempty local and domain parts")
    if any(ch.isspace() for ch in email):
        raise ValueError("email must not contain whitespace")
    if not name:
        raise ValueError("name must not be empty")
    return email, name

def import_contacts(connection, rows):
    if not isinstance(rows, (list, tuple)):
        raise ValueError("rows must be a list")
    # Validate the entire batch before touching the database.
    batch = []
    seen = set()
    for row in rows:
        email, name = _normalize_row(row)
        if email in seen:
            raise ValueError(f"duplicate email in batch: {email}")
        seen.add(email)
        batch.append((email, name))
    if not batch:
        return {"inserted": 0, "updated": 0}
    # One transaction: any database failure rolls back every write.
    with connection:
        existing = existing_emails(connection, (email for email, _ in batch))
        inserted = 0
        updated = 0
        for email, name in batch:
            put_contact(connection, email, name)
            if email in existing:
                updated += 1
            else:
                inserted += 1
    return {"inserted": inserted, "updated": updated}
